mapper.select:
select distinct a.*, cp.id 'project.id', cp.name 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', m.id 'monomer.id', m.name 'monomer.name', ar.id 'area.id', ar.name 'area.name', batch.name AS areaBatchName, u.name as user_name FROM tech_artifact AS a left join sys_user as u on a.user_id = u.id and u.bool_delete_enum = 0 left join contract_project cp on a.project_id = cp.id and cp.bool_delete_enum = 0 left join plan_monomer m on a.monomer_id = m.id and m.bool_delete_enum = 0 left join plan_area ar on a.area_id = ar.id and ar.bool_delete_enum = 0 left join plan_area_batch batch on a.area_batch_id = batch.id and batch.bool_delete_enum = 0
INNER JOIN sys_monomer_user_link AS link ON m.id = link.monomer_id AND link.bool_delete_enum = 0 AND link.deepened_person_id = #{userId}
where a.bool_delete_enum = 0
AND a.project_id = #{projectId}
AND a.monomer_id = #{monomerId}
AND a.area_id = #{areaId}
AND a.area_batch_id = #{areaBatchId}
AND a.structure_class_id = #{structureClassId}
AND a.bool_status_enum = #{status}
AND a.area_type = #{areaType}
And a.name like concat('%',#{name},'%')
AND a.serial_number like concat('%',#{serialNumber},'%')
AND a.specification like concat('%',#{specification},'%')
AND a.material like concat('%',#{material},'%')
AND a.bool_scheduling_enum = #{boolSchedulingEnum}
AND a.artifact_type = #{artifactType}

select distinct a.id, a.name, a.serial_number, a.specification, a.length, a.material, a.net_weight, a.gross_weight, a.surface_area, a.drawing_number, a.remark, a.bool_status_enum, a.artifact_type, a.bool_send_directly, a.structure_class_id, m.id AS monomerId, es.quantity, es.quantity * a.net_weight AS total_net_weight, es.quantity * a.gross_weight AS total_gross_weight, cp.id 'project.id', cp.name 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', m.id 'monomer.id', m.name 'monomer.name', ar.id 'area.id', ar.name 'area.name', u.name as user_name, es.batch_number FROM ( SELECT ext.batch_number, ext.artifact_id, sum(quantity) quantity FROM tech_artifact_ext AS ext WHERE ext.bool_delete_enum = 0
and ext.batch_number like concat('%',#{batchNumber},'%')
AND ext.area_id = #{areaId}
AND ext.serial_number like concat('%',#{serialNumber},'%')
GROUP BY ext.batch_number, ext.artifact_id ) AS es LEFT JOIN tech_artifact a on a.id = es.artifact_id and a.bool_delete_enum = 0 left join sys_user as u on a.user_id = u.id and u.bool_delete_enum = 0 left join contract_project cp on a.project_id = cp.id and cp.bool_delete_enum = 0 left join plan_monomer m on a.monomer_id = m.id and m.bool_delete_enum = 0 left join plan_area ar on a.area_id = ar.id and ar.bool_delete_enum = 0 where a.bool_delete_enum = 0
AND a.project_id = #{projectId}
AND a.monomer_id = #{monomerId}
AND a.area_id = #{areaId}
AND a.structure_class_id = #{structureClassId}
AND a.bool_status_enum = #{status}
AND a.area_type = #{areaType}
And a.name like concat('%',#{name},'%')
AND a.specification like concat('%',#{specification},'%')
AND a.material like concat('%',#{material},'%')
AND a.bool_scheduling_enum = #{boolSchedulingEnum}
AND a.artifact_type = #{artifactType}

select ifnull(sum(quantity),0) quantity,
ifnull(sum(total_net_weight),0) mete,
ifnull(sum(total_gross_weight),0) mete_two
from tech_artifact
where bool_delete_enum = 0

    and project_id = #{projectId}


    and monomer_id = #{monomerId}


    and area_id = #{areaId}

select project_id,ifnull(sum(quantity),0) quantity, ifnull(sum(total_net_weight),0) mete from tech_artifact where bool_delete_enum = 0
and project_id = #{projectId}
group by project_id

select d.`id` 'area.id', d.`name` 'area.name', ifnull(sum(a.quantity), 0) quantity, ifnull(sum(a.total_net_weight), 0) total_net_weight, ifnull(sum(a.total_gross_weight), 0) total_gross_weight, ROUND( ifnull( sum( a.surface_area * a.quantity ), 0 ) / 1000000, 4 ) AS total_area, ROUND( ifnull( sum( a.top_flange_area * a.quantity ), 0 ) / 1000000, 4 ) AS top_flange_area, ifnull(sum(a.total_drawing_weight), 0) AS total_drawing_weight from tech_artifact a inner join plan_area d on d.id = a.area_id and d.bool_delete_enum = 0
INNER JOIN sys_monomer_user_link AS link ON a.monomer_id = link.monomer_id AND link.bool_delete_enum = 0 AND link.deepened_person_id = #{userId}
where a.bool_delete_enum = 0 and a.monomer_id = #{monomerId} group by d.id

select *
from tech_artifact
where id = #{id}

select ta.*, ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ARTIFACT.getType()} As productType, pa.name AS areaName, m.name AS monomerName from tech_artifact ta LEFT JOIN plan_area pa on pa.id = ta.area_id LEFT JOIN plan_monomer m on m.id = ta.monomer_id where ta.bool_delete_enum = 0
AND ta.area_id in
#{areaId}
AND ta.monomer_id = #{monomerId}
and ta.serial_number = #{serialNumber}
limit 1

select ta.*, ${@com.hzchum.scim.common.core.api.enums.ProductTypeEnum@ARTIFACT.getType()} As productType, pa.name AS areaName, m.name AS monomerName from tech_artifact ta LEFT JOIN plan_area pa on pa.id = ta.area_id LEFT JOIN plan_monomer m on m.id = ta.monomer_id where ta.bool_delete_enum = 0
AND ta.area_id in
#{areaId}
AND ta.monomer_id = #{monomerId}
and ta.serial_number = #{serialNumber}
limit 1

Select`name`, serial_number, specification, quantity, length, net_weight, gross_weight from tech_artifact where
structure_class_id in ( SELECT id FROM sys_structure_classification WHERE bool_delete_enum = 0 and classification_name=#{classificationName} )
structure_class_id is null
and material=#{material}
and project_id=#{projectId}
and bool_delete_enum=0

SELECT sum(IFNULL((process.need_quantity - complete_quantity),a.quantity)) AS quantity, c.id id, c.classification_name name FROM `tech_artifact` a INNER JOIN mes_building_task_process process ON process.product_id = a.id and process.task_type_enum = 2 AND process.sequence = 0 and process.bool_delete_enum = 0 LEFT JOIN sys_structure_classification c ON a.structure_class_id = c.id WHERE a.bool_delete_enum = 0 and IFNULL((process.need_quantity - complete_quantity),0) > 0 and a.quantity > a.produced_quantity AND c.id IS NOT NULL
AND a.project_id = #{projectId}
AND a.monomer_id = #{monomerId}
AND a.area_id = #{areaId}
GROUP BY c.id

SELECT a.id id, a.project_id, a.monomer_id, a.area_id, a.name, a.serial_number, a.specification, a.material, a.length, a.net_weight, a.total_net_weight, a.gross_weight, a.total_gross_weight, a.surface_area AS area, IFNULL( SUM( process.complete_quantity ), 0 ) produced_quantity, IFNULL(( SUM(process.need_quantity)), 0) AS quantity, IFNULL(( SUM(process.need_quantity) - SUM(complete_quantity) ), 0 ) AS needQuantity FROM `tech_artifact` a INNER JOIN mes_building_task_process process ON process.product_id = a.id and process.task_type_enum = 2 and process.sequence = 0 and process.bool_delete_enum = 0 WHERE a.bool_delete_enum = 0 and a.bool_all_part_send_directly=0 and IFNULL((process.need_quantity - complete_quantity),0) > 0 and a.quantity > a.produced_quantity
and a.id in
#{id}
AND a.project_id = #{projectId}
AND a.monomer_id = #{monomerId}
AND a.area_id = #{areaId}
AND a.area_batch_id = #{areaBatchId}
AND a.structure_class_id = #{structureClassId}
AND a.name like concat('%',#{name},'%')
AND a.serial_number like concat('%',#{serialNumber},'%')
AND a.specification like concat('%',#{specification},'%')
AND a.material like concat('%',#{material},'%')
GROUP BY a.id

SELECT b.id id, b.classification_name name, sum(a.quantity) quantity, sum(a.total_net_weight) mete FROM tech_artifact a LEFT JOIN sys_structure_classification b ON a.structure_class_id = b.id WHERE a.bool_delete_enum = 0 and a.area_type = 1
AND a.project_id = #{projectId}
AND a.monomer_id = #{monomerId}
AND a.area_id = #{areaId}
GROUP BY b.id ,b.classification_name

SELECT temp.structure_class_id, class.classification_name structure_class_name, COUNT(temp.serial_number) quantity FROM ( SELECT a.monomer_id, a.serial_number, a.structure_class_id FROM tech_artifact a WHERE a.bool_delete_enum = 0 AND a.project_id = #{projectId}
AND a.monomer_id = #{monomerId}
GROUP BY a.monomer_id, a.serial_number, structure_class_id ) temp INNER JOIN sys_structure_classification class ON class.id = temp.structure_class_id AND class.bool_delete_enum = 0 GROUP BY temp.structure_class_id

SELECT a.project_id 'project.id', cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', a.monomer_id, m.`name` monomer_name, a.structure_class_id, class.classification_name as structure_class_name, a.serial_number, a.`name`, a.specification, a.material FROM tech_artifact a LEFT JOIN contract_project cp on cp.id = a.project_id AND cp.bool_delete_enum = 0 LEFT JOIN plan_monomer m ON a.monomer_id = m.id AND m.bool_delete_enum = 0 LEFT JOIN sys_structure_classification class ON a.structure_class_id = class.id AND class.bool_delete_enum = 0 WHERE a.bool_delete_enum = 0
AND a.project_id = #{projectId}
AND a.monomer_id = #{monomerId}
and a.structure_class_id in
#{structureClassId}
and a.name like concat('%',#{name},'%')
and a.serial_number like concat('%',#{serialNumber},'%')
and a.specification like concat('%',#{specification},'%')
and a.material like concat('%',#{material},'%')
GROUP BY a.project_id, a.monomer_id, a.structure_class_id, a.serial_number, a.`name`, a.specification, a.material

select a.* from ( select a.id, a.`name`, a.specification, a.serial_number, GROUP_CONCAT( DISTINCT b.number ) number, a.create_time, c.id 'project.id', c.name 'project.name', c.serial_number 'project.serial_number', c.short_name 'project.short_name', d.id 'monomer.id', d.name 'monomer.name', e.id 'area.id', e.name 'area.name' from tech_artifact a left join mes_building_produce_team_report b on a.id = b.product_id left join contract_project c on a.project_id = c.id left join plan_monomer d on a.monomer_id = d.id left join plan_area e on a.area_id = e.id where a.bool_delete_enum = 0 and b.bool_delete_enum = 0 and b.task_type_enum = 2 and a.production_line_type_enum = 1 and a.serial_number like concat( '%', #{serialNumber}, '%' )
and a.project_id = #{projectId}
and a.monomer_id = #{monomerId}
and a.area_id = #{areaId}
group by a.id, c.id, d.id, e.id, a.serial_number, a.specification ) a order by CHAR_LENGTH( a.serial_number ), a.create_time desc

select a.id, a.`name`, a.specification, a.serial_number, a.create_time, c.id 'project.id', c.name 'project.name', c.serial_number 'project.serial_number', c.short_name 'project.short_name', d.id 'monomer.id', d.name 'monomer.name', e.id 'area.id', e.name 'area.name' from tech_artifact a left join contract_project c on a.project_id = c.id left join plan_monomer d on a.monomer_id = d.id left join plan_area e on a.area_id = e.id where a.bool_delete_enum = 0 and a.serial_number like concat( '%', #{serialNumber}, '%' )
and a.project_id = #{projectId}
and a.monomer_id = #{monomerId}
and a.area_id = #{areaId}

SELECT a.id, a.`name`, a.specification, a.serial_number, a.specification, cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', m.`id` 'monomer.id', m.`name` 'monomer.name', ar.id 'area.id', ar.name 'area.name' FROM tech_artifact a LEFT JOIN contract_project cp on cp.id = a.project_id AND cp.bool_delete_enum = 0 LEFT JOIN plan_monomer m ON a.monomer_id = m.id AND m.bool_delete_enum = 0 LEFT JOIN sys_structure_classification class ON a.structure_class_id = class.id AND class.bool_delete_enum = 0 LEFT JOIN plan_area ar on a.area_id = ar.id and ar.bool_delete_enum = 0 WHERE a.bool_delete_enum = 0
AND a.project_id = #{projectId}
AND a.area_id = #{areaId}
AND a.monomer_id = #{monomerId}
AND a.serial_number = #{serialNumber}

SELECT distinct a.id, a.`name`, a.specification, a.serial_number, a.specification, cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', m.`id` 'monomer.id', m.`name` 'monomer.name', ar.id 'area.id', ar.name 'area.name' FROM mes_building_complete complete LEFT JOIN tech_artifact a on complete.product_id = a.id and a.bool_delete_enum =0 LEFT JOIN contract_project cp on cp.id = a.project_id AND cp.bool_delete_enum = 0 LEFT JOIN plan_monomer m ON a.monomer_id = m.id AND m.bool_delete_enum = 0 LEFT JOIN sys_structure_classification class ON a.structure_class_id = class.id AND class.bool_delete_enum = 0 LEFT JOIN plan_area ar on a.area_id = ar.id and ar.bool_delete_enum = 0 LEFT JOIN mes_building_warehouse_record record on complete.product_id = record.product_id and complete.number = record.number and complete.id = record.complete_id and record.bool_delete_enum = 0 and record.product_type = 2 and record.type = 1 WHERE complete.bool_delete_enum = 0 and complete.task_type_enum = 2 and complete.bool_spot_check = false and record.status in(1,2)
AND a.project_id = #{projectId}
AND a.area_id = #{areaId}
AND a.monomer_id = #{monomerId}
AND a.serial_number = #{serialNumber}

SELECT a.serial_number FROM tech_artifact a LEFT JOIN contract_project cp on cp.id = a.project_id AND cp.bool_delete_enum = 0 LEFT JOIN plan_monomer m ON a.monomer_id = m.id AND m.bool_delete_enum = 0 LEFT JOIN sys_structure_classification class ON a.structure_class_id = class.id AND class.bool_delete_enum = 0 LEFT JOIN plan_area ar on a.area_id = ar.id and ar.bool_delete_enum = 0 WHERE a.bool_delete_enum = 0
AND a.project_id = #{projectId}
AND a.area_id = #{areaId}
AND a.monomer_id = #{monomerId}
AND a.serial_number like concat('%',#{serialNumber},'%')

SELECT distinct a.serial_number FROM mes_building_complete complete LEFT JOIN tech_artifact a on complete.product_id = a.id and a.bool_delete_enum =0 LEFT JOIN contract_project cp on cp.id = a.project_id AND cp.bool_delete_enum = 0 LEFT JOIN plan_monomer m ON a.monomer_id = m.id AND m.bool_delete_enum = 0 LEFT JOIN sys_structure_classification class ON a.structure_class_id = class.id AND class.bool_delete_enum = 0 LEFT JOIN plan_area ar on a.area_id = ar.id and ar.bool_delete_enum = 0 LEFT JOIN mes_building_warehouse_record record on complete.product_id = record.product_id and complete.number = record.number and complete.id = record.complete_id and record.bool_delete_enum = 0 and record.product_type = 2 and record.type = 1 WHERE complete.bool_delete_enum = 0 and complete.task_type_enum = 2 and complete.bool_spot_check = false and record.status in(1,2)
AND a.project_id = #{projectId}
AND a.area_id = #{areaId}
AND a.monomer_id = #{monomerId}
AND a.serial_number like concat('%',#{serialNumber},'%')

select ta.Id, ta.name, serial_number serialNumber, specification specification, sum(task.task_quantity) taskQuantity from tech_artifact ta inner join mes_building_task task on ta.id = task.product_id and task.bool_delete_enum = 0 where ta.bool_delete_enum = 0
and ta.project_id in
#{userProjectId}
and ta.monomer_id = #{monomerId}
and ta.area_id = #{areaId}
and ta.structure_class_id = #{classId}
and ta.serial_number like concat('%',#{serialNumber},'%')
and ta.area_id in
#{areaId}
group by ta.id

select ta.id, ta.name, ta.serial_number , ta.quantity, ta.produced_quantity from tech_artifact ta where ta.bool_delete_enum = 0 and ta.project_id = #{projectId}
and ta.monomer_id = #{monmerId}
and ta.area_id = #{areaId}
and ta.serial_number like concat('%',#{serialNumber},'%')
and ta.name like concat('%',#{name},'%')
and ta.specification like concat('%',#{specification},'%')
and ta.material like concat('%',#{material},'%')

        select
        *
        from tech_assemble_record ta
        where ta.monomer_id = #{monomerId}
          and ta.area_id = #{areaId}
          and ta.inventory_operation_id = #{inventoryOperationId}
          and ta.serial_number like concat(#{serialNumber},'%')

SELECT a.id id, a.project_id, a.monomer_id, a.area_id, a.name, a.serial_number, a.specification, a.material, a.length, a.net_weight, a.total_net_weight, a.gross_weight, a.total_gross_weight, a.surface_area AS area, IFNULL( SUM( process.complete_quantity ), 0 ) produced_quantity, IFNULL(( SUM(process.need_quantity)), 0) AS quantity, IFNULL(( SUM(process.need_quantity) - SUM(complete_quantity) ), 0 ) AS needQuantity FROM `tech_artifact` a INNER JOIN mes_building_task_process process ON process.product_id = a.id and process.task_type_enum = 2 and process.sequence = 0 and process.bool_delete_enum = 0 WHERE a.bool_delete_enum = 0 and a.bool_all_part_send_directly=0 and IFNULL((process.need_quantity - complete_quantity),0) > 0 and a.quantity > a.produced_quantity
and process.task_order_id = #{taskOrderId}
GROUP BY a.id
